"""Behavioral development contract for the previously exposed iter_index issue."""
import unittest

from more_itertools import iter_index


class Index:
    def __init__(self, value):
        self.value = value

    def __index__(self):
        return self.value


class TraceIterator:
    def __init__(self, values):
        self.values = iter(values)
        self.reads = []

    def __iter__(self):
        return self

    def __next__(self):
        value = next(self.values)
        self.reads.append(value)
        return value


class OriginalMaintenanceContract(unittest.TestCase):
    def test_negative_bounds_match_absolute_slice_indices(self):
        for data in ('', 'A', 'ABBA', 'AABCADEAF'):
            for start in range(-12, 13):
                for stop in (None, -20, -9, -4, -1, 0, 1, 4, 9, 20):
                    included = range(*slice(start, stop).indices(len(data)))
                    expected = [i for i, x in enumerate(data) if i in included and x == 'A']
                    for wrap in (list, tuple, iter):
                        with self.subTest(data=data, start=start, stop=stop, wrap=wrap):
                            self.assertEqual(list(iter_index(wrap(data), 'A', start, stop)), expected)

    def test_no_matches_and_empty_intervals(self):
        for data in ('', 'BCDEF', 'AABCADEAF'):
            for start, stop in ((0, None), (1, 4), (-4, None), (0, -1), (-1, -4)):
                expected = [i for i in range(*slice(start, stop).indices(len(data))) if data[i] == 'Z']
                self.assertEqual(list(iter_index(iter(data), 'Z', start, stop)), expected)


class CompatibilityContract(unittest.TestCase):
    def test_positive_index_protocol_start_and_stop(self):
        for start, stop in ((Index(1), 7), (1, Index(7)), (Index(1), Index(7))):
            with self.subTest(start=start, stop=stop):
                self.assertEqual(list(iter_index(iter('AABCADEAF'), 'A', start, stop)), [1, 4])

    def test_negative_and_mixed_index_protocol(self):
        for start, stop, expected in (
            (Index(-8), Index(-2), [1, 4]),
            (Index(-20), None, [0, 1, 4, 7]),
            (Index(1), Index(-2), [1, 4]),
            (Index(-4), Index(8), [7]),
            (Index(8), Index(-1), []),
        ):
            with self.subTest(start=start, stop=stop):
                self.assertEqual(list(iter_index(iter('AABCADEAF'), 'A', start, stop)), expected)

    def test_positive_bounds_are_lazy_and_leave_the_tail(self):
        source = TraceIterator('AABCADEAF')
        found = iter_index(source, 'A', Index(1), Index(7))
        self.assertEqual(source.reads, [])
        self.assertEqual(next(found), 1)
        self.assertEqual(source.reads, ['A', 'A'])
        self.assertEqual(list(found), [4])
        self.assertEqual(source.reads, list('AABCADE'))
        self.assertEqual(next(source), 'A')
        self.assertEqual(next(source), 'F')

    def test_int_positive_bounds_remain_lazy(self):
        source = TraceIterator([0, 1, 0, 2, 0, 3])
        found = iter_index(source, 0, 1, 4)
        self.assertEqual(source.reads, [])
        self.assertEqual(next(found), 2)
        self.assertEqual(source.reads, [0, 1, 0])
        self.assertEqual(list(found), [])
        self.assertEqual(next(source), 0)

    def test_noninteger_bound_is_not_silently_truncated(self):
        class IntOnly:
            def __int__(self):
                return 1

        for invalid in (1.0, 1.5, IntOnly()):
            for start, stop in ((invalid, 7), (1, invalid)):
                source = TraceIterator('AABCADEAF')
                with self.subTest(start=start, stop=stop):
                    with self.assertRaises((TypeError, ValueError)):
                        list(iter_index(source, 'A', start, stop))
                    self.assertEqual(source.reads, [])

    def test_sequence_fast_path_matching_semantics(self):
        self.assertEqual(list(iter_index('ABCDABCD', 'AB')), [0, 4])
        self.assertEqual(list(iter_index([0, 1, 2, 0, 1], [0, 1])), [])
        self.assertEqual(list(iter_index([[0, 1], [2, 3], [0, 1]], [0, 1])), [0, 2])

    def test_identity_precedes_equality(self):
        class BadEquality:
            def __eq__(self, other):
                raise RuntimeError('identity must avoid equality')

        value = BadEquality()
        for start, stop in ((0, None), (-2, None), (Index(0), Index(2))):
            self.assertEqual(list(iter_index(iter([value, value]), value, start, stop)), [0, 1])

    def test_comparison_business_exception_is_preserved(self):
        for marker in (ValueError('comparison'), RuntimeError('comparison')):
            class BadEquality:
                def __eq__(self, other):
                    raise marker

            for start, stop in ((1, 2), (-2, -1)):
                source = iter([0, BadEquality(), 2])
                with self.subTest(error=type(marker).__name__, start=start):
                    with self.assertRaises(type(marker)) as caught:
                        list(iter_index(source, 'needle', start, stop))
                    self.assertIs(caught.exception, marker)
                    if start == 1:
                        self.assertEqual(next(source), 2)

    def test_iteration_business_exception_is_preserved(self):
        for marker in (ValueError('iteration'), RuntimeError('iteration')):
            def source():
                yield 'A'
                raise marker

            found = iter_index(source(), 'A', -1)
            with self.assertRaises(type(marker)) as caught:
                list(found)
            self.assertIs(caught.exception, marker)


if __name__ == '__main__':
    unittest.main()
